const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // reads PG* env vars
const router = express.Router();

router.get('/orders', async (req, res, next) => {
  const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

  let cursor = null;
  if (req.query.cursor) {
    try {
      cursor = JSON.parse(Buffer.from(String(req.query.cursor), 'base64url').toString());
    } catch {}
    if (typeof cursor?.createdAt !== 'string' || typeof cursor?.id !== 'string') {
      return res.status(400).json({ error: 'invalid cursor' });
    }
  }

  try {
    // created_at::text keeps microseconds; a JS Date would truncate to ms
    // and skip or repeat rows at page boundaries.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
         ${cursor ? 'WHERE (created_at, id) < ($2::timestamptz, $3::bigint)' : ''}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      cursor ? [limit + 1, cursor.createdAt, cursor.id] : [limit + 1]
    );

    const page = rows.slice(0, limit);
    const last = page.at(-1);
    const nextCursor = rows.length > limit
      ? Buffer.from(JSON.stringify({ createdAt: last.cursor_ts, id: String(last.id) })).toString('base64url')
      : null;

    res.json({ data: page.map(({ cursor_ts, ...order }) => order), nextCursor });
  } catch (err) {
    // class 22 = bad timestamp/id inside a tampered cursor
    if (cursor && err.code?.startsWith('22')) {
      return res.status(400).json({ error: 'invalid cursor' });
    }
    next(err);
  }
});

module.exports = router;
```

