import assert from "node:assert/strict";
import { JobQueue } from "./job-queue";

async function demo() {
  const queue = new JobQueue(2);
  const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
  let active = 0, peak = 0, flakyCalls = 0, doomedCalls = 0;

  for (let i = 0; i < 6; i++) {
    void queue.add(async () => {
      peak = Math.max(peak, ++active);
      await sleep(10);
      active--;
    });
  }
  const flaky = queue.add(async () => {
    if (++flakyCalls < 3) throw new Error("flaky");
    return "done";
  });
  const doomed = assert.rejects(
    queue.add(async () => {
      doomedCalls++;
      throw new Error("always");
    }),
    /always/,
  );

  await queue.onIdle();
  assert.equal(peak, 2);
  assert.equal(await flaky, "done");
  assert.equal(flakyCalls, 3);
  await doomed;
  assert.equal(doomedCalls, 4); // 1 try + 3 retries
  console.log("ok");
}

demo();
```

I haven't run this here; `npx tsx job-queue.test.ts` should print `ok`.

- **Retries:** "up to three times" is read as one initial try plus three retries, so a job runs at most four times. Retries are immediate and keep the job's concurrency slot.
- **Failures:** `add()` returns a promise that rejects once a job has failed for good. Attach a `.catch` or `await` it, or Node will treat it as an unhandled rejection. `onIdle()` resolves regardless of failures.

